module TopModule (
    input clk,
    input reset,
    input ena,
    output pm,
    output [7:0] hh,
    output [7:0] mm,
    output [7:0] ss
);

    reg [3:0] hh_tens, hh_ones;
    reg [3:0] mm_tens, mm_ones;
    reg [3:0] ss_tens, ss_ones;
    reg pm_reg;

    always @(posedge clk) begin
        if (reset) begin
            // Reset to 12:00:00 AM
            hh_tens <= 4'd1;
            hh_ones <= 4'd2;
            mm_tens <= 4'd0;
            mm_ones <= 4'd0;
            ss_tens <= 4'd0;
            ss_ones <= 4'd0;
            pm_reg <= 1'b0; // AM
        end else if (ena) begin
            if (ss_ones == 4'd9 && ss_tens == 4'd5) begin
                ss_ones <= 4'd0;
                ss_tens <= 4'd0;
                if (mm_ones == 4'd9 && mm_tens == 4'd5) begin
                    mm_ones <= 4'd0;
                    mm_tens <= 4'd0;
                    if (hh_tens == 4'd1 && hh_ones == 4'd2) begin
                        // 12:59:59 -> 01:00:00 (PM flips)
                        hh_tens <= 4'd0;
                        hh_ones <= 4'd1;
                        pm_reg <= ~pm_reg;
                    end else if (hh_tens == 4'd1 && hh_ones == 4'd1) begin
                        // 11:59:59 -> 12:00:00 (PM flips)
                        hh_tens <= 4'd1;
                        hh_ones <= 4'd2;
                        pm_reg <= ~pm_reg;
                    end else begin
                        // 01-10: increment hh
                        if (hh_ones == 4'd9) begin
                            hh_ones <= 4'd0;
                            hh_tens <= hh_tens + 4'd1;
                        end else begin
                            hh_ones <= hh_ones + 4'd1;
                        end
                    end
                end else begin
                    // mm increment
                    if (mm_ones == 4'd9) begin
                        mm_ones <= 4'd0;
                        mm_tens <= mm_tens + 4'd1;
                    end else begin
                        mm_ones <= mm_ones + 4'd1;
                    end
                end
            end else begin
                // ss increment
                if (ss_ones == 4'd9) begin
                    ss_ones <= 4'd0;
                    ss_tens <= ss_tens + 4'd1;
                end else begin
                    ss_ones <= ss_ones + 4'd1;
                end
            end
        end
    end

    assign hh = {hh_tens, hh_ones};
    assign mm = {mm_tens, mm_ones};
    assign ss = {ss_tens, ss_ones};
    assign pm = pm_reg;

endmodule
